mapper.select:
SELECT COUNT(DISTINCT d.animal_cage_id)
FROM cage_cell_detail d
JOIN cage_cell_index ci ON ci.animal_cage_id = d.animal_cage_id
JOIN cage_shelf_index si ON si.id = ci.shelf_index_id
WHERE si.room_id = #{roomId}
  AND d.aup_number = #{registerNo}

SELECT COALESCE(rent_number, 0)
FROM cage_booking_room_aup
WHERE room_id = #{roomId}
  AND register_number = #{registerNo}
  AND deleted = 0
LIMIT 1
